   803	    /// [`load`](Self::load)). A record this build cannot read is skipped
   804	    /// with a warning; a missing folder holds none.
   805	    pub fn list(&self) -> io::Result<Vec<StoredRun>> {
   806	        let entries = match fs::read_dir(&self.dir) {
   807	            Ok(entries) => entries,
   808	            Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
   809	            Err(error) => return Err(error),
   810	        };
