   812	        for entry in entries.flatten() {
   813	            let name = entry.file_name();
   814	            let Some(run_id) = name.to_str().and_then(|n| n.strip_suffix(RECORD_SUFFIX)) else {
   815	                continue;
   816	            };
   817	            if !crate::job_log::valid_id(run_id) {
   818	                continue;
   819	            }
   820	            let record = match fs::read(entry.path()).and_then(|bytes| read_record(&bytes)) {
   821	                Ok(record) => record,
   822	                Err(error) => {
   823	                    log::warn!("job records: skipping {}: {error}", entry.path().display());
   824	                    continue;
   825	                }
   826	            };
   827	            runs.push(StoredRun {
   828	                spec_path: self.path(run_id, SPEC_SUFFIX),
   829	                record_path: entry.path(),
   830	                record: self.settled(record),
   831	            });
   832	        }
   833	        runs.sort_by(|a, b| {
   834	            b.record
   835	                .started_ms
   836	                .cmp(&a.record.started_ms)
   837	                .then_with(|| b.record.run_id.cmp(&a.record.run_id))
   838	        });
   839	        Ok(runs)
   840	    }
