   842	    /// Remove the oldest runs beyond the newest `keep`, never one running
   843	    /// or waiting on a daemon; returns the runs removed. Holds the folder's
   844	    /// prune lock throughout, so two runs finishing at once do not race.
   845	    ///
   846	    /// JOB_LOGS jl-5 (FAST): newest by when each record was last written —
   847	    /// a record is replaced whole, so an ended run's time is its end and a
   848	    /// running one's its start; the order the log folder's
   849	    /// [`prune`](crate::job_log::prune) keeps — with names breaking ties.
   850	    /// Only the records beyond the newest `keep` are read, each settled
   851	    /// (see [`load`](Self::load)); one this build cannot read is left.
   852	    pub fn prune(&self, keep: usize) -> io::Result<Vec<String>> {
   853	        let lock = match open_lock(&self.dir.join(PRUNE_LOCK)) {
   854	            Ok(lock) => lock,
   855	            Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
   856	            Err(error) => return Err(error),
   857	        };
   858	        lock.lock()?;
   859	        let mut records = Vec::new();
   860	        for entry in fs::read_dir(&self.dir)?.flatten() {
   861	            let name = entry.file_name();
   862	            let Some(run_id) = name.to_str().and_then(|n| n.strip_suffix(RECORD_SUFFIX)) else {
   863	                continue;
   864	            };
   865	            if !crate::job_log::valid_id(run_id) {
   866	                continue;
   867	            }
   868	            let Ok(meta) = entry.metadata() else { continue };
   869	            let Ok(modified) = meta.modified() else {
   870	                continue;
   871	            };
   872	            if meta.is_file() {
   873	                records.push((modified, run_id.to_string()));
   874	            }
   875	        }
   876	        // Newest first; names break ties so the order is the same every time.
   877	        records.sort_by(|a, b| b.cmp(a));
   878	        let mut removed = Vec::new();
   879	        for (_, run_id) in records.into_iter().skip(keep) {
   880	            let record_path = self.path(&run_id, RECORD_SUFFIX);
   881	            let record = match fs::read(&record_path).and_then(|bytes| read_record(&bytes)) {
   882	                Ok(record) => self.settled(record),
   883	                Err(error) => {
   884	                    log::warn!(
   885	                        "job records: not pruning {}: {error}",
   886	                        record_path.display()
   887	                    );
   888	                    continue;
   889	                }
   890	            };
   891	            if matches!(record.state, RunState::Running | RunState::Waiting { .. }) {
   892	                continue;
   893	            }
   894	            match fs::remove_file(&record_path) {
   895	                Ok(()) => {
   896	                    let _ = fs::remove_file(self.path(&run_id, SPEC_SUFFIX));
   897	                    removed.push(run_id);
   898	                }
   899	                Err(error) => {
   900	                    log::warn!("job records: could not prune run {run_id}: {error}")
   901	                }
   902	            }
   903	        }
   904	        Ok(removed)
   905	    }
   906	}
