from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
import re, subprocess
def read_job(pair):
    osname, job = pair
    res = subprocess.run(["gh", "api", "--allow-escape-sequences", f"/repos/roethlar/Blit/actions/jobs/{job}/logs"], capture_output=True)
    if res.returncode:
        return (osname, res.stderr.decode(errors="replace")[:350])
    plain = re.sub(rb"\x1b\[[0-?]*[ -/]*[@-~]", b"", res.stdout).decode(errors="replace")
    lines = ["".join(c for c in line if c.isprintable() or c == "\t") for line in plain.splitlines()]
    Path(".review-local", f"{osname}-ci.log").write_text("\n".join(lines))
    include = set()
    for i, line in enumerate(lines):
        if re.search(r"\.\.\. FAILED|panicked at|test result: FAILED|\[error\]|Error:|^error:", line):
            include.update(range(max(0,i-1),min(len(lines),i+9)))
    return osname, "\n".join(lines[i][:650] for i in sorted(include)[-85:])
with ThreadPoolExecutor(2) as pool:
    for name, result in pool.map(read_job, [("linux",138889887872),("macos",138889888286)]):
        print(name)
        print(result)
