   419	pub fn spawn_daemon(
   420	    workspace: &Path,
   421	    name: &str,
   422	    module_dir: &Path,
   423	    opts: &DaemonOptions,
   424	) -> SpawnedDaemon {
   425	    ensure_daemon_built();
   426	
   427	    // What is already there is exported as it stands: a module may be
   428	    // one file (cr-uv5-5).
   429	    if !module_dir.exists() {
   430	        fs::create_dir_all(module_dir).expect("module dir");
   431	    }
   432	    let config_path = workspace.join(format!("{name}.toml"));
   433	    // The daemon canonicalizes exported roots before serving them. Matching
   434	    // the unique temporary module path proves the RPC response came from this
   435	    // child, rather than from any process that happened to own the port first.
   436	    let expected_module_path = module_dir.canonicalize().expect("canonical module dir");
   437	    let readiness_runtime = tokio::runtime::Builder::new_current_thread()
   438	        .enable_all()
   439	        .build()
   440	        .expect("daemon readiness runtime");
   441	
   442	    for attempt in 1..=DAEMON_STARTUP_ATTEMPTS {
   443	        let port = pick_unused_port();
   444	        let config = DaemonConfig {
   445	            daemon: DaemonSection {
   446	                bind: "127.0.0.1".into(),
   447	                port,
   448	                no_mdns: true,
   449	            },
   450	            modules: vec![ModuleSection {
   451	                name: "test".into(),
   452	                path: module_dir.to_path_buf(),
   453	                comment: None,
   454	                read_only: opts.read_only,
   455	                delegation_allowed: true,
   456	            }],
   457	            delegation: opts.delegation.then(|| DelegationSection {
   458	                allow_delegated_pull: true,
   459	                // Loopback sources must be authorized by IP/CIDR form, not
   460	                // hostname form. This mirrors the production SSRF rule.
   461	                allowed_source_hosts: vec!["127.0.0.1".to_string()],
   462	            }),
   463	        };
   464	        let toml = toml::to_string(&config).expect("serialize config");
   465	        fs::write(&config_path, toml).expect("write config");
   466	
   467	        let mut cmd = Command::new(daemon_bin());
   468	        cmd.arg("--config")
   469	            .arg(&config_path)
   470	            .arg("--bind")
   471	            .arg("127.0.0.1")
   472	            .arg("--port")
   473	            .arg(port.to_string());
   474	        for arg in &opts.extra_args {
   475	            cmd.arg(arg);
   476	        }
   477	        // The daemon's own state (job logs, perf history) stays in this
   478	        // test's workspace, never the developer's config folder.
   479	        cmd.env("STATE_DIRECTORY", workspace.join(format!("{name}-state")));
   480	        // Drain stderr concurrently so daemon logging cannot fill an unread pipe.
   481	        // The bounded tail is retained for readiness failures and test panics.
   482	        let mut child = cmd
   483	            .stdin(Stdio::null())
   484	            .stdout(Stdio::null())
   485	            .stderr(Stdio::piped())
   486	            .spawn()
   487	            .expect("spawn daemon");
   488	        let stderr = child.stderr.take().expect("take daemon stderr");
   489	        let mut daemon = ChildGuard::new(child, StderrCapture::start(stderr));
   490	
   491	        let readiness = wait_for_owned_readiness(
   492	            50,
   493	            Duration::from_millis(100),
   494	            || {
   495	                daemon
   496	                    .child
   497	                    .as_mut()
   498	                    .expect("daemon child present during readiness")
   499	                    .try_wait()
   500	                    .map(|status| status.map(|status| status.to_string()))
   501	                    .map_err(|err| format!("poll spawned daemon: {err}"))
   502	            },
   503	            || daemon_identity_matches(&readiness_runtime, port, &expected_module_path),
