mod common;
use std::ffi::OsString;
use std::fs;
use std::os::unix::ffi::OsStringExt;
use std::process::Command;
use std::time::Duration;
use common::{TestContext,run_with_timeout};

#[test]
fn a_granted_text_with_a_later_raw_sibling() {
    let ctx = TestContext::new();
    let src = ctx.workspace.join("src");
    fs::create_dir(&src).unwrap();
    let text = "dup\u{fffd}";
    let raw = OsString::from_vec(b"dup\xff".to_vec());
    fs::write(src.join(text), b"first text").unwrap();
    for i in 0..8192 {
        let name = format!("filler{i:05}");
        fs::write(src.join(&name), b"").unwrap();
        fs::write(ctx.module_dir.join(name), b"").unwrap();
    }
    fs::write(src.join(&raw), b"second raw").unwrap();
    let mut send = Command::new(&ctx.cli_bin);
    send.arg("--config-dir").arg(&ctx.config_dir).args(["copy", "-v", "--retries", "0", "--force-grpc", "--size-only"])
        .arg(format!("{}/",src.display())).arg(format!("127.0.0.1:{}:/test/",ctx.daemon_port));
    let sent = run_with_timeout(send, Duration::from_secs(80));
    let stderr = String::from_utf8_lossy(&sent.stderr);
    assert_eq!(sent.status.code(),Some(2),"{}",stderr);
    let run_id = stderr.lines().find_map(|line| line.strip_prefix("blit: job ")).and_then(|rest| rest.split_whitespace().next()).unwrap();
    let mut get = Command::new(&ctx.cli_bin);
    get.arg("--config-dir").arg(&ctx.config_dir).args(["jobs","log",run_id,"--json"]);
    let shown=run_with_timeout(get,Duration::from_secs(20));
    assert!(shown.status.success());
    let events:Vec<serde_json::Value>=String::from_utf8_lossy(&shown.stdout).lines().map(|line|serde_json::from_str(line).unwrap()).collect();
    let names:Vec<_>=events.iter().filter(|e|e["kind"]=="file-sent" && e["path"]==text).map(|e|e["raw"].clone()).collect();
    println!("source log for the grant: {names:?}; text destination={:?}; raw destination exists={}", fs::read(ctx.module_dir.join(text)).ok(),ctx.module_dir.join(raw).exists());
    assert_eq!(fs::read(ctx.module_dir.join(text)).unwrap(), b"first text");
    assert_eq!(names,vec![serde_json::Value::Null],"a text file was sent");
}
